mapper.select:
SELECT EXISTS(
    SELECT 1
    FROM attendance_report_oa_evidence_exclusion excl
    WHERE excl.company_id = #{companyId}
      AND excl.employee_id = #{employeeId}
      AND excl.attendance_source_id = #{attendanceSourceId}
      AND excl.source_business_key = #{sourceBusinessKey}
      AND excl.source_version = #{sourceVersion}
      AND excl.oa_attendance_document_id = #{oaAttendanceDocumentId}
      AND excl.knowledge_at <= #{asOf}
      AND (excl.reversed_at IS NULL OR excl.reversed_at > #{asOf})
)

SELECT EXISTS(
    SELECT 1
    FROM attendance_report_oa_overtime_recognition recog
    WHERE recog.company_id = #{companyId}
      AND recog.employee_id = #{employeeId}
      AND recog.attendance_source_id = #{attendanceSourceId}
      AND recog.business_date = #{businessDate}
      AND recog.expected_interval_start < #{intervalEnd}
      AND recog.expected_interval_end > #{intervalStart}
      AND recog.oa_attendance_document_id <> #{excludeDocId}
      AND recog.knowledge_at <= #{asOf}
      AND (recog.reversed_at IS NULL OR recog.reversed_at > #{asOf})
)
